import java.util.Scanner;

public class EmailConverter {
    public static int locateSubstring(String str, String pattern, int startIdx) {
        for (int i = startIdx; i <= str.length() - pattern.length(); i++) {
            if (str.charAt(i) == pattern.charAt(0)) {
                boolean matchFound = true;
                for (int j = 1; j < pattern.length(); j++) {
                    if (str.charAt(i + j) != pattern.charAt(j)) {
                        matchFound = false;
                        break;
                    }
                }
                if (matchFound) return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String email = scanner.nextLine();
        int atPos = locateSubstring(email, "at", 1);
        String temp = email.substring(0, atPos) + '@' + email.substring(atPos + 2);
        int dotPos = locateSubstring(temp, "dot", 1);
        StringBuilder output = new StringBuilder();
        int startIdx = 0;
        while (dotPos != -1 && dotPos < temp.length() - 3) {
            output.append(temp.substring(startIdx, dotPos)).append('.');
            startIdx = dotPos + 3;
            dotPos = locateSubstring(temp, "dot", startIdx);
        }
        output.append(temp.substring(startIdx));
        System.out.print(output.toString());
        scanner.close();
    }
}
